/**
 * Home page.
 * @module src/routes/index
 */

import React from 'react';

import * as styles from './index.less';

/**
 * Slide configuration object.
 * @typedef {object} Slide
 * @property {number} index - The slide's index number.
 * @property {React.Component} Content - The slide's React component.
 */

const slidesCtx = import.meta.webpackContext(
    './slides/', {
        include: /\.md$/,
    },
);

/**
 * Configure slides.
 * @param {string} slidePath - Slide module path.
 * @returns {module:src/routes/index~Slide} The configured slide.
 */
function slideConfigure(slidePath) {
    const index = Number.parseInt(slidePath.match(/\/(\d\d)\.md$/)[1]);
    const Component = slidesCtx(slidePath).default;
    return { index, Component };
}

const slides = slidesCtx.keys()
    .map(slideConfigure)
    .sort((a, b) => a.index - b.index);

/**
 * Slide component.
 * @param {object} props - The component's props.
 * @param {React.ReactElement} props.children - The component's children.
 * @returns {React.ReactElement} The component's elements.
 */
function Slide({ children }) {
    return (
        <div className={styles.slide}>
            {children}
        </div>
    );
}

/**
 * Home page component.
 * @returns {React.ReactElement} The component's elements.
 */
export default function Home() {
    const slideElems = slides.map((slide) => (
        <Slide key={slide.index}>
            <slide.Component />
        </Slide>
    ));
    return (
        <>
            {slideElems}
        </>
    );
}
